SELECT property_code, name, dashboard_id, id FROM properties WHERE UPPER(property_code) = 'DVH';
UPDATE dashboard_bookings SET property_id = (SELECT COALESCE(NULLIF(TRIM(dashboard_id), ''), id) FROM properties WHERE UPPER(property_code) = 'DVH'), property_code = 'DVH', property_name = (SELECT name FROM properties WHERE UPPER(property_code) = 'DVH') WHERE UPPER(property_code) = 'GH-KBP' AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'DVH');
UPDATE finance_entries SET property_id = (SELECT COALESCE(NULLIF(TRIM(dashboard_id), ''), id) FROM properties WHERE UPPER(property_code) = 'DVH'), property_name = (SELECT name FROM properties WHERE UPPER(property_code) = 'DVH') WHERE (UPPER(property_id) = 'BELUM-GH-KBP' OR property_id IN (SELECT id FROM properties WHERE UPPER(property_code) = 'GH-KBP') OR property_id IN (SELECT dashboard_id FROM properties WHERE UPPER(property_code) = 'GH-KBP')) AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'DVH');
UPDATE dashboard_management_data SET data_json = json_set(data_json, '$.properties', COALESCE((SELECT json_group_array(json(value)) FROM json_each(dashboard_management_data.data_json, '$.properties') WHERE UPPER(COALESCE(json_extract(value, '$.code'), '')) <> 'GH-KBP'), json('[]'))) WHERE id = 'main';
DELETE FROM properties WHERE UPPER(property_code) = 'GH-KBP' AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'DVH');
SELECT (SELECT COUNT(*) FROM properties WHERE UPPER(property_code) = 'GH-KBP') AS sisa_properti_GHKBP, (SELECT COUNT(*) FROM dashboard_bookings WHERE UPPER(property_code) = 'GH-KBP') AS sisa_booking_GHKBP, (SELECT COUNT(*) FROM dashboard_bookings WHERE UPPER(property_code) = 'DVH') AS booking_DVH, (SELECT COALESCE(SUM(amount), 0) FROM dashboard_bookings WHERE UPPER(property_code) = 'DVH') AS total_booking_DVH;
